//! The append-only session log: one line per step, written as it happens.
//!
//! # Why a log and not a document
//!
//! A document is the shape a consumer wants, and it is the wrong shape to
//! write during a session. Rewriting the whole document after every step
//! costs bytes quadratic in the session's length, and — the part that
//! matters — a process killed partway through that rewrite leaves a
//! truncated file that parses as nothing at all. The record would be lost
//! exactly when there is most reason to want it.
//!
//! So a session appends. Each record is one complete JSON object on one
//! line, flushed and synced before the call returns. A session that is
//! killed loses at most the line it was in the middle of writing, and
//! [`read`] skips an unreadable line rather than refusing the file, so
//! everything before it still reads back. [`Recording::document`] renders
//! the ATIF document from the lines on read, which is why the log and the
//! document can never disagree: there is only one of them.
//!
//! # Two ways to read
//!
//! [`read`] recovers. It splits the file into lines as bytes before it
//! decodes any of them, so a final record torn in the middle of a
//! multibyte character costs that record and nothing before it. Every line
//! that did not contribute is a [`Fault`] on the recording, with its line
//! number and what was wrong, and the recording says whether the session
//! ended or was interrupted. That is the reader for a person looking at a
//! trace.
//!
//! [`read_whole`] is the reader for evidence. It refuses a log with any
//! fault, and a log with no `end` record, so a recovered prefix cannot pass
//! as a complete session. A grader reads through it, or checks
//! [`Recording::whole`] itself, and treats anything less as unverifiable.
//!
//! # The lifecycle a log holds to
//!
//! One `session` record, first. Then steps. Then at most one `end` record,
//! last. A second `session` record, a second `end`, or any record after
//! `end` is a fault: the first header and the first ending stand, and the
//! record at fault is not read. A line that is not UTF-8, not JSON, not a
//! known record, or a record whose payload does not read as its type is a
//! fault too. A final line with no newline was never finished, so it is a
//! fault even when its bytes happen to parse.
//!
//! # The records
//!
//! ```text
//! {"record":"session","schema_version":"ATIF-v1.7","at":…,"session":{…}}
//! {"record":"step","step":{…}}
//! {"record":"end","at":…,"state":"ended"}
//! ```
//!
//! The `session` record comes first and is never rewritten, so it holds only
//! what is true when the session opens. How the session ended and how long
//! it took are computed on read — from the `end` record when there is one,
//! and from the last step when there is not. A log with no `end` record is
//! a session that was interrupted, and it says so.

use std::fmt;
use std::fs::{self, File, OpenOptions};
use std::io::{self, Write};
use std::path::{Path, PathBuf};

use serde_json::{Map, Value, json};

use crate::document::{self, Session, Step};

/// The extension a session log carries. Two parts: `.jsonl` says how to
/// read the file, and `.atif` says what the lines mean.
pub const EXTENSION: &str = "atif.jsonl";

/// The state a log with no closing record reads back as.
pub const INTERRUPTED: &str = "interrupted";

/// The state a session that closed itself reads back as.
pub const ENDED: &str = "ended";

/// A session log open for writing.
///
/// Every [`append`](Log::append) writes one line and syncs it. The cost is
/// one `fsync` per step, which for a conversational agent is a handful per
/// turn, each already separated by a network round trip. That is the price
/// of the guarantee, and it is not a price worth haggling over.
#[derive(Debug)]
pub struct Log {
    path: PathBuf,
    file: File,
    steps: usize,
    closed: bool,
}

impl Log {
    /// Opens a new log for `session` in `dir`, creating the directory when
    /// it is missing.
    ///
    /// The file is named for the session and must not already exist: a
    /// session that would overwrite another session's record is a bug, not
    /// a thing to do quietly.
    ///
    /// # Errors
    ///
    /// Returns the underlying filesystem error when the directory cannot be
    /// created or the file cannot be written.
    pub fn create(dir: &Path, session: &Session) -> io::Result<Self> {
        fs::create_dir_all(dir)?;
        // These are the user's own conversations. The directory is theirs.
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let _ = fs::set_permissions(dir, fs::Permissions::from_mode(0o700));
        }
        Self::create_at(&dir.join(format!("{}.{EXTENSION}", session.id)), session)
    }

    /// Opens a new log for `session` at `path`, creating the parent
    /// directory when it is missing.
    ///
    /// A caller that names the file owns the name, so this does not derive
    /// one from the session. The file must not already exist, for the same
    /// reason [`Log::create`] refuses to overwrite one.
    ///
    /// # Errors
    ///
    /// Returns the underlying filesystem error when the directory cannot be
    /// created or the file cannot be written.
    pub fn create_at(path: &Path, session: &Session) -> io::Result<Self> {
        if let Some(parent) = path
            .parent()
            .filter(|parent| !parent.as_os_str().is_empty())
        {
            fs::create_dir_all(parent)?;
        }
        let path = path.to_path_buf();
        let mut file = OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&path)?;
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let _ = fs::set_permissions(&path, fs::Permissions::from_mode(0o600));
        }
        let header = json!({
            "record": "session",
            "schema_version": document::SCHEMA_VERSION,
            "at": document::now_ms(),
            "session": session,
        });
        write_line(&mut file, &header)?;
        Ok(Log {
            path,
            file,
            steps: 0,
            closed: false,
        })
    }

    /// The file this log writes to.
    #[must_use]
    pub fn path(&self) -> &Path {
        &self.path
    }

    /// How many steps have been written.
    #[must_use]
    pub fn steps(&self) -> usize {
        self.steps
    }

    /// Appends one step and syncs it to disk.
    ///
    /// # Errors
    ///
    /// Returns the underlying filesystem error. A caller that cannot record
    /// should say so and carry on: a trace is evidence about a conversation,
    /// not a part of it. Returns an `InvalidInput` error, and writes
    /// nothing, when the log has been [finished](Log::finish): a step after
    /// the end would be a fault on read.
    pub fn append(&mut self, step: &Step) -> io::Result<()> {
        if self.closed {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!(
                    "{} is finished; a step cannot follow the end",
                    self.path.display()
                ),
            ));
        }
        write_line(&mut self.file, &json!({ "record": "step", "step": step }))?;
        self.steps += 1;
        Ok(())
    }

    /// Closes the log with how the session ended. A second call does
    /// nothing, so an explicit close and a close on drop cannot write two
    /// endings.
    ///
    /// # Errors
    ///
    /// Returns the underlying filesystem error.
    pub fn finish(&mut self, state: &str) -> io::Result<()> {
        if self.closed {
            return Ok(());
        }
        self.closed = true;
        write_line(
            &mut self.file,
            &json!({ "record": "end", "at": document::now_ms(), "state": state }),
        )
    }
}

/// Writes one record as one line, then flushes and syncs it.
///
/// The sync is the whole point of the module: without it the line sits in
/// the operating system's cache, and a killed process leaves a file that is
/// shorter than what the agent had already done.
fn write_line(file: &mut File, record: &Value) -> io::Result<()> {
    let mut line = serde_json::to_string(record).map_err(io::Error::other)?;
    line.push('\n');
    file.write_all(line.as_bytes())?;
    file.flush()?;
    file.sync_data()
}

/// A session log read back.
#[derive(Clone, Debug)]
pub struct Recording {
    /// The session, with `state`, `seconds`, and `directive` filled in from
    /// what the log turned out to hold.
    pub session: Session,
    /// The steps, in the order they were written.
    pub steps: Vec<Step>,
    /// Lines that did not contribute a record: the count of
    /// [`faults`](Self::faults). A session killed mid-write leaves one.
    pub unreadable_lines: usize,
    /// Every line that did not contribute a record, in file order, with
    /// what was wrong with it.
    pub faults: Vec<Fault>,
    /// Where the log was read from.
    pub path: PathBuf,
}

impl Recording {
    /// The ATIF document this recording renders as.
    ///
    /// `extra` carries `source_path`, `unreadable_lines`, and `faults`, so
    /// a document rendered from a damaged log says so.
    #[must_use]
    pub fn document(&self) -> Value {
        let mut document = document::document(&self.session, &self.steps);
        if let Some(extra) = document.get_mut("extra").and_then(Value::as_object_mut) {
            extra.insert(
                "source_path".to_string(),
                json!(self.path.display().to_string()),
            );
            extra.insert("unreadable_lines".to_string(), json!(self.unreadable_lines));
            extra.insert(
                "faults".to_string(),
                Value::Array(
                    self.faults
                        .iter()
                        .map(|fault| json!({"line": fault.line, "fault": fault.kind.word()}))
                        .collect(),
                ),
            );
        }
        document
    }

    /// Whether the session closed itself.
    #[must_use]
    pub fn ended(&self) -> bool {
        self.session.state == ENDED
    }

    /// Whether the log is fit for evidence: every line read as a record and
    /// the session ended. A recovered prefix is not whole, however much of
    /// it there is.
    #[must_use]
    pub fn whole(&self) -> bool {
        self.faults.is_empty() && self.ended()
    }
}

/// One line of a log that did not contribute a record.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Fault {
    /// The line, counting from 1.
    pub line: usize,
    /// What was wrong with it.
    pub kind: FaultKind,
}

impl fmt::Display for Fault {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "line {}: {}", self.line, self.kind)
    }
}

/// What kept a line from being read as a record.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FaultKind {
    /// The final line has no newline: the writer did not finish it.
    Torn,
    /// The bytes are not UTF-8.
    NotUtf8,
    /// The text is not a JSON object.
    NotJson,
    /// The object's `record` names no record kind this reader knows.
    UnknownRecord,
    /// A `session` record whose payload does not read as a session.
    BadSession,
    /// A `step` record whose payload does not read as a step.
    BadStep,
    /// A `session` record after the first; the first stands.
    RepeatedSession,
    /// An `end` record after the first; the first stands.
    RepeatedEnd,
    /// A record after the `end` record.
    AfterEnd,
    /// A record before the `session` record.
    BeforeSession,
}

impl FaultKind {
    /// The fault as one `snake_case` word, for a document.
    #[must_use]
    pub fn word(self) -> &'static str {
        match self {
            Self::Torn => "torn",
            Self::NotUtf8 => "not_utf8",
            Self::NotJson => "not_json",
            Self::UnknownRecord => "unknown_record",
            Self::BadSession => "bad_session",
            Self::BadStep => "bad_step",
            Self::RepeatedSession => "repeated_session",
            Self::RepeatedEnd => "repeated_end",
            Self::AfterEnd => "after_end",
            Self::BeforeSession => "before_session",
        }
    }
}

impl fmt::Display for FaultKind {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(match self {
            Self::Torn => "the last line was never finished",
            Self::NotUtf8 => "the line is not UTF-8",
            Self::NotJson => "the line is not a JSON object",
            Self::UnknownRecord => "the record kind is unknown",
            Self::BadSession => "the session does not read",
            Self::BadStep => "the step does not read",
            Self::RepeatedSession => "a second session record",
            Self::RepeatedEnd => "a second end record",
            Self::AfterEnd => "a record after the end",
            Self::BeforeSession => "a record before the session",
        })
    }
}

/// Reads a session log, recovering what it can.
///
/// Every line that did not contribute is a [`Fault`] on the recording;
/// [`Recording::whole`] says whether there were none and the session
/// ended. Read evidence through [`read_whole`] instead.
///
/// # Errors
///
/// Returns the underlying filesystem error, or an `InvalidData` error when
/// the file holds no session record and so is not a session log.
pub fn read(path: &Path) -> io::Result<Recording> {
    let bytes = fs::read(path)?;
    let mut opened: Option<(u64, Session)> = None;
    let mut steps: Vec<Step> = Vec::new();
    let mut closed: Option<(u64, String)> = None;
    let mut faults: Vec<Fault> = Vec::new();

    let mut lines: Vec<&[u8]> = bytes.split(|byte| *byte == b'\n').collect();
    // A file that ends in a newline splits into one empty piece past the
    // last line; a file that does not ends in a line the writer never
    // finished.
    let torn = match lines.last() {
        Some([]) => {
            lines.pop();
            false
        }
        Some(_) => true,
        None => false,
    };
    let count = lines.len();

    for (index, raw) in lines.into_iter().enumerate() {
        let number = index + 1;
        let mut fault = |kind: FaultKind| faults.push(Fault { line: number, kind });
        if torn && number == count {
            fault(FaultKind::Torn);
            continue;
        }
        let Ok(line) = std::str::from_utf8(raw) else {
            fault(FaultKind::NotUtf8);
            continue;
        };
        if line.trim().is_empty() {
            continue;
        }
        let Ok(record) = serde_json::from_str::<Map<String, Value>>(line) else {
            fault(FaultKind::NotJson);
            continue;
        };
        let kind = record.get("record").and_then(Value::as_str);
        if !matches!(kind, Some("session" | "step" | "end")) {
            fault(FaultKind::UnknownRecord);
            continue;
        }
        if closed.is_some() {
            fault(if kind == Some("end") {
                FaultKind::RepeatedEnd
            } else {
                FaultKind::AfterEnd
            });
            continue;
        }
        if opened.is_none() && kind != Some("session") {
            fault(FaultKind::BeforeSession);
            continue;
        }
        let at = record.get("at").and_then(Value::as_u64).unwrap_or_default();
        match kind {
            Some("session") if opened.is_some() => fault(FaultKind::RepeatedSession),
            Some("session") => {
                match record
                    .get("session")
                    .cloned()
                    .and_then(|value| serde_json::from_value::<Session>(value).ok())
                {
                    Some(session) => opened = Some((at, session)),
                    None => fault(FaultKind::BadSession),
                }
            }
            Some("step") => match record
                .get("step")
                .cloned()
                .and_then(|value| serde_json::from_value::<Step>(value).ok())
            {
                Some(step) => steps.push(step),
                None => fault(FaultKind::BadStep),
            },
            _ => {
                let state = record
                    .get("state")
                    .and_then(Value::as_str)
                    .unwrap_or(ENDED)
                    .to_string();
                closed = Some((at, state));
            }
        }
    }
    let Some((started, mut session)) = opened else {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("{} holds no session record", path.display()),
        ));
    };
    let last = closed
        .as_ref()
        .map(|(at, _)| *at)
        .or_else(|| steps.last().map(|step| step.at))
        .unwrap_or(started);
    session.seconds = last.saturating_sub(started) / 1_000;
    session.state = match &closed {
        Some((_, state)) => state.clone(),
        None => INTERRUPTED.to_string(),
    };
    if session.directive.is_empty() {
        session.directive = steps
            .iter()
            .find(|step| step.source == document::Source::User)
            .map(|step| step.message.clone())
            .unwrap_or_default();
    }
    Ok(Recording {
        session,
        steps,
        unreadable_lines: faults.len(),
        faults,
        path: path.to_path_buf(),
    })
}

/// Reads a session log as evidence.
///
/// # Errors
///
/// Returns what [`read`] returns, and an `InvalidData` error naming the
/// first fault when any line did not read, or saying the session was
/// interrupted when it holds no `end` record. Nothing recovered passes.
pub fn read_whole(path: &Path) -> io::Result<Recording> {
    let recording = read(path)?;
    if let Some(fault) = recording.faults.first() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "{} is damaged at {fault}{}",
                path.display(),
                match recording.faults.len() {
                    1 => String::new(),
                    more => format!(" and {} more", more - 1),
                }
            ),
        ));
    }
    if !recording.ended() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "{} holds no end record: the session was interrupted",
                path.display()
            ),
        ));
    }
    Ok(recording)
}

/// The directory a session writes to when nothing says otherwise:
/// `~/.openagents/traces`. `None` when the home directory is unknown.
#[must_use]
pub fn default_dir() -> Option<PathBuf> {
    let home = std::env::var_os("HOME")?;
    if home.is_empty() {
        return None;
    }
    Some(PathBuf::from(home).join(".openagents").join("traces"))
}

/// The session logs in `dir`, oldest first. The name carries the start
/// time, so sorting by name sorts by time.
///
/// # Errors
///
/// Returns the underlying filesystem error when the directory cannot be
/// read.
pub fn list(dir: &Path) -> io::Result<Vec<PathBuf>> {
    let mut found: Vec<PathBuf> = fs::read_dir(dir)?
        .filter_map(Result::ok)
        .map(|entry| entry.path())
        .filter(|path| {
            path.file_name()
                .and_then(|name| name.to_str())
                .is_some_and(|name| name.ends_with(EXTENSION))
        })
        .collect();
    found.sort();
    Ok(found)
}

/// A session identifier: the UTC start time, then eight hex digits that
/// separate two sessions started in the same second.
///
/// The time leads so that a directory listing is a history, and the file
/// name is the identifier so that a document and the file it came from
/// cannot drift apart.
#[must_use]
pub fn session_id(at: u64) -> String {
    let nanos = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|since| since.subsec_nanos())
        .unwrap_or_default();
    let salt = u64::from(nanos) ^ (u64::from(std::process::id()) << 19);
    format!("{}-{:08x}", document::stamp(at), salt as u32)
}

//! The Agent Trajectory Interchange Format: a session as ordered steps.
//!
//! The transcript a person reads is rows in a terminal, which is the wrong
//! shape for analysis: it says what a person saw, not what the agent did. A
//! session therefore keeps a second record of itself as ordered steps, and
//! this crate is that record — both the format, in [`document`], and the
//! file a running session appends to, in [`log`].
//!
//! The format is ATIF as the Harbor trajectory RFC defines it, reimplemented
//! here from the reference implementation in `~/work/coder`. It is a schema,
//! not service code: nothing in this crate opens a socket, and nothing in it
//! knows where a trace goes afterwards.
//!
//! # Why this format
//!
//! Because a decision-model call is first-class data in it. A shell command
//! and a question put to Jev, Kev, or Lev are both [`Call`]s, and
//! [`Call::extra`] carries what the host knows beyond the wire fields — which
//! door answered, what it was asked, what it said, and the digest of the
//! state it read. [`Decision`] builds one.
//!
//! That is the half of the picture the Gym's rows cannot supply. A row is
//! per-decision: one door, one state, one answer, comparable across doors. A
//! trace is per-episode: ordered, and holding what happened *next*, which is
//! what an outcome label is derived from.
//!
//! # What is not capped
//!
//! Nothing here truncates a tool result. Capping output is what makes a trace
//! useless for the analysis it exists for: a record of a command whose output
//! has been cut is a record that cannot answer whether the agent had what it
//! needed. A trace holds what the process held. Where the process itself
//! already bounded something — `coder`'s shell caps its capture, and shows its
//! judge less than it captured — the call's `extra` records that bound, so a
//! reader can tell what the agent saw from what the machine said.
//!
//! # Writing one
//!
//! ```no_run
//! use atif::{Log, Session, Source, Step, log};
//!
//! let dir = log::default_dir().expect("a home directory");
//! let session = Session::opening(
//!     &log::session_id(atif::now_ms()),
//!     "google/gemini-3.8-flash",
//!     "live",
//!     "/Users/someone/work/openagents",
//!     env!("CARGO_PKG_VERSION"),
//! );
//! let mut log = Log::create(&dir, &session)?;
//! log.append(&Step::said(Source::User, "what crates are here"))?;
//! log.finish(atif::log::ENDED)?;
//!
//! let document = atif::log::read(log.path())?.document();
//! # Ok::<(), std::io::Error>(())
//! ```

pub mod document;
pub mod log;

pub use document::{
    AGENT_NAME, Call, DECISION_CALL_SCHEMA, Decision, EXPORTER, Outcome, SCHEMA_VERSION, Session,
    Source, Step, Usage, digest, document, intent, iso, now_ms, stamp,
};
pub use log::{Fault, FaultKind, Log, Recording};

/// How the episode ended.
///
/// A trace records that the session closed itself; it does not record what
/// the turn concluded. So a trace read on its own is [`Ending::Closed`],
/// and the exit code the driver saw is what promotes it to
/// [`Ending::Answered`]. That difference is the one the driver used to
/// print and then drop.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub enum Ending {
    /// The turn finished and the agent answered.
    Answered,
    /// The turn finished and the router declined it. Nothing went wrong.
    Declined,
    /// The turn did not finish.
    Failed,
    /// The turn ran past the task's timeout and was stopped.
    TimedOut,
    /// The trace closed itself and does not say how the turn ended.
    Closed,
    /// Nothing observed the ending.
    #[default]
    Unobserved,
    /// Something else, which the word carries.
    Other(String),
}

impl Ending {
    /// The word a task's `endings` list spells this with.
    #[must_use]
    pub fn word(&self) -> &str {
        match self {
            Self::Answered => "answered",
            Self::Declined => "declined",
            Self::Failed => "failed",
            Self::TimedOut => "timed_out",
            Self::Closed => "closed",
            Self::Unobserved => "unobserved",
            Self::Other(word) => word,
        }
    }
}

/// Everything wrong with a run, named.
///
/// Each fault carries its own [`Verdict`] through [`Fault::verdict`], so a
/// list of faults says which of them were measured and which of them nobody
/// could measure.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Fault {
    /// The run selected a program the task did not expect.
    Program { expected: String, found: String },
    /// The run started the wrong number of delegations.
    DelegationCount { expected: usize, found: usize },
    /// The task expects a delegation asking this, and the run recorded
    /// none in its place.
    DelegationMissing { prompt: String },
    /// The delegation in a slot asked a different question than the one
    /// the task pins there. A reordered, duplicated, or substituted
    /// delegation reads the same way: the recorded prompt is not the
    /// expected one.
    DelegationMisattributed {
        id: String,
        wanted: String,
        found: String,
    },
    /// A delegation's recorded output is not the answer the task expects.
    DelegationAnswered {
        id: String,
        wanted: String,
        found: String,
    },
    /// A delegation the run started did not answer correctly.
    DelegationWrong { id: String },
    /// A delegation did not complete.
    DelegationFailed { id: String, outcome: String },
    /// A delegation recorded no correctness either way, or recorded one
    /// with no answer to show for it.
    DelegationUnverified { id: String },
    /// Fewer delegations are recorded correct than the task requires.
    DelegationsCorrect {
        expected: usize,
        verified: usize,
        unverified: usize,
    },
    /// A decision the task expects was never asked.
    DecisionMissing { name: String },
    /// A decision was asked and the call did not complete.
    DecisionFailed { name: String, outcome: String },
    /// A decision was asked and came back with no answers.
    DecisionUnanswered { name: String },
    /// A decision did not answer a question the task reads.
    AnswerMissing { decision: String, question: String },
    /// A decision answered a question the wrong way.
    AnswerWrong {
        decision: String,
        question: String,
        wanted: String,
        found: String,
    },
    /// A deterministic check the task expects never ran.
    CheckMissing { name: String },
    /// A check ran under the expected name and did not complete.
    CheckFailed { name: String, outcome: String },
    /// A step ran before one the path puts ahead of it.
    OutOfOrder { step: String, before: String },
    /// The run wrote where the task expects no writes.
    UnexpectedWrite { path: String },
    /// The run wrote a different number of files than the task expects.
    WriteCount { expected: usize, found: usize },
    /// Nothing compared the workspace, so what the run wrote is unknown.
    WritesUnobserved,
    /// The episode ended a way the task does not allow.
    Ended { found: String, allowed: Vec<String> },
    /// Nothing observed how the episode ended.
    EndingUnobserved { allowed: Vec<String> },
    /// The trace closed without saying how the episode ended.
    EndingUnstated { allowed: Vec<String> },
    /// The trace has no end record, so the session never closed itself.
    Unfinished,
    /// Part of the trace did not read back.
    TornTrace { lines: usize },
    /// The task's own expectation cannot check a run: it pins no prompt or
    /// no answer, repeats a prompt, or states a count that disagrees with
    /// the delegations it pins. This is a fault about the manifest rather
    /// than about the run, and a manifest that cannot check cannot pass.
    ExpectationMalformed { why: String },
}

impl Fault {
    /// What this fault establishes.
    ///
    /// Measured and wrong is [`Verdict::Failed`]. Missing evidence is
    /// [`Verdict::Unverifiable`], which is not a pass and is not a failure.
    #[must_use]
    pub fn verdict(&self) -> Verdict {
        match self {
            Self::Program { .. }
            | Self::DelegationCount { .. }
            | Self::DelegationMissing { .. }
            | Self::DelegationMisattributed { .. }
            | Self::DelegationAnswered { .. }
            | Self::ExpectationMalformed { .. }
            | Self::DelegationWrong { .. }
            | Self::DelegationFailed { .. }
            | Self::DecisionMissing { .. }
            | Self::DecisionFailed { .. }
            | Self::AnswerWrong { .. }
            | Self::CheckMissing { .. }
            | Self::CheckFailed { .. }
            | Self::OutOfOrder { .. }
            | Self::UnexpectedWrite { .. }
            | Self::WriteCount { .. }
            | Self::Ended { .. }
            | Self::Unfinished => Verdict::Failed,
            Self::DelegationUnverified { .. }
            | Self::DecisionUnanswered { .. }
            | Self::AnswerMissing { .. }
            | Self::WritesUnobserved
            | Self::EndingUnobserved { .. }
            | Self::EndingUnstated { .. }
            | Self::TornTrace { .. } => Verdict::Unverifiable,
            // A shortfall the unverified delegations could still cover is
            // unknown. One they could not cover is measured and short.
            Self::DelegationsCorrect {
                expected,
                verified,
                unverified,
            } => {
                if verified + unverified >= *expected {
                    Verdict::Unverifiable
                } else {
                    Verdict::Failed
                }
            }
        }
    }
}

/// What a task concluded about a run.
#[derive(Clone, Debug)]
pub struct Judgment {
    pub verdict: Verdict,
    /// Every fault, in the order [`Grade::path`] states.
    pub faults: Vec<Fault>,
}

impl Judgment {
    /// Whether the run took the path the task expects, with the evidence to
    /// show it.
    #[must_use]
    pub fn passed(&self) -> bool {
        self.verdict == Verdict::Passed
    }
}

/// What a run did, read back out of its trace and off the machine it ran
/// on.
#[derive(Clone, Debug, Default)]
pub struct Observed {
    pub program: Option<String>,
    pub delegations: Vec<Delegation>,
    /// The decisions the run asked, by name, with what came back.
    pub decisions: BTreeMap<String, Asked>,
    /// Deterministic calls the run made, in order, with how they ended.
    pub checks: Vec<Check>,
    /// Every call's name, in the order the trace records it, delegations
    /// and all. This is what the step order is judged against.
    pub order: Vec<String>,
    /// Writes a call reported making. A self-report: the ones it names
    /// count, and the ones it does not name establish nothing.
    pub writes: Vec<String>,
    /// What the workspace said, read independently of the run.
    pub workspace: Option<Workspace>,
    /// How the episode ended.
    pub ending: Ending,
    /// Whether the trace holds an end record.
    pub closed: bool,
    /// Lines of the trace that did not read back.
    pub unreadable_lines: usize,
}

/// Judges what a run did against the path this task expects.
///
/// Returns every fault rather than the first, because a run that took
/// the wrong program usually gets several things wrong afterwards and
/// the first one is rarely the informative one.
///
/// The faults come back in the order [`Grade::path`] states, so the
/// first one is the earliest thing that went wrong. Reporting them in
/// the order the checker tests them would put a missing delegation
/// above the missing probe that explains it. Faults about the record
/// itself sort after every step, because they are about the trace
/// rather than about a place in the path.
#[must_use]
pub fn judge(&self, run: &Observed) -> Judgment {
    let mut faults = Vec::new();
    self.judge_program(run, &mut faults);
    self.judge_delegations(run, &mut faults);
    self.judge_decisions(run, &mut faults);
    self.judge_checks(run, &mut faults);
    self.judge_order(run, &mut faults);
    self.judge_writes(run, &mut faults);
    self.judge_record(run, &mut faults);
    // A stable sort, so faults that share a step keep the order they
    // were found in: how many delegations ran, then which of them
    // answered wrongly, then what they wrote.
    faults.sort_by_key(|fault| self.stage(fault));
    let verdict = if faults.is_empty() {
        Verdict::Passed
    } else {
        Verdict::over(faults.iter().map(Fault::verdict))
    };
    Judgment { verdict, faults }
}

/// Whether the record is whole, and whether the episode ended a way the
/// task allows.
fn judge_record(&self, run: &Observed, faults: &mut Vec<Fault>) {
    if !run.closed {
        faults.push(Fault::Unfinished);
    }
    if run.unreadable_lines > 0 {
        faults.push(Fault::TornTrace {
            lines: run.unreadable_lines,
        });
    }
    let allowed = self.grade.allowed();
    if allowed.iter().any(|word| word == run.ending.word()) {
        return;
    }
    match &run.ending {
        Ending::Unobserved => faults.push(Fault::EndingUnobserved { allowed }),
        Ending::Closed => faults.push(Fault::EndingUnstated { allowed }),
        found => faults.push(Fault::Ended {
            found: found.word().to_string(),
            allowed,
        }),
    }
}

/// Whether a decision came back with nothing anybody can read.
fn empty_answers(answers: &Value) -> bool {
    match answers {
        Value::Object(map) => map.is_empty(),
        _ => true,
    }
}

/// Reads an ATIF trace back into the shape [`Task::judge`] reads.
///
/// What the trace holds is kept rather than summarized: how each call
/// ended, whether the session closed itself, how many lines did not read
/// back, and the order the calls came in. A grade that cannot see those
/// cannot tell a run that worked from a run that stopped halfway with the
/// right names in it.
///
/// # Errors
///
/// Returns an error when the trace cannot be read.
pub fn observe(path: &Path) -> Result<Observed, String> {
    let recording = atif::log::read(path).map_err(|e| format!("{}: {e}", path.display()))?;
    let closed = recording.ended();
    let mut out = Observed {
        closed,
        unreadable_lines: recording.unreadable_lines,
        // A trace says the session closed itself and not what the turn
        // concluded. Only an exit code says that, and only a driver sees
        // one.
        ending: if closed {
            Ending::Closed
        } else {
            Ending::Unobserved
        },
        ..Observed::default()
    };
    for step in &recording.steps {
        let Some(call) = &step.call else { continue };
        out.order.push(call.name.clone());
        // A decision renders as a call carrying the decision-call schema in
        // `extra`, so a reader tells the two apart by that rather than by
        // the call's name.
        if call.is_decision() {
            let answers = call.extra.get("answers").cloned().unwrap_or(Value::Null);
            if call.name == PROGRAM_CALL {
                out.program = answers
                    .get("program")
                    .and_then(|a| a.get("choice"))
                    .and_then(|c| c.as_str())
                    .map(str::to_string);
            }
            out.decisions.insert(
                call.name.clone(),
                Asked {
                    answers,
                    outcome: call.outcome,
                },
            );
        } else {
            out.checks.push(Check {
                name: call.name.clone(),
                outcome: call.outcome,
            });
            if call.name == DELEGATE_CALL {
                out.delegations.push(Delegation {
                    id: call.id.clone(),
                    prompt: call
                        .arguments
                        .get("prompt")
                        .and_then(Value::as_str)
                        .unwrap_or_default()
                        .to_string(),
                    output: call.output.clone(),
                    milliseconds: call.milliseconds,
                    outcome: call.outcome,
                    correct: call.extra.get("correct").and_then(Value::as_bool),
                });
            }
            match call.extra.get("wrote") {
                Some(Value::String(written)) => out.writes.push(written.clone()),
                Some(Value::Array(written)) => out
                    .writes
                    .extend(written.iter().filter_map(Value::as_str).map(str::to_string)),
                _ => {}
            }
        }
    }
    Ok(out)
}
